$\log_{10}2=0.3010$，$\log_{10}3=0.4771$ とする．
\begin{enumerate}
  \item $3^{100}$ は何桁の整数か．また，最高位の数字を求めよ．
  \item $2^n$ がちょうど100桁となる自然数 $n$ をすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\log_23>\dfrac32>\log_35$ を示せ．
  \item $2^{30},\ 3^{20},\ 5^{12}$ を小さい順に並べよ．
  \item $\log_34>\log_45$ を示せ．
\end{enumerate}

\begin{enumerate}
  \item 方程式 $4^x+4^{-x}-3(2^x+2^{-x})+4=0$ を解け．
  \item 不等式 $2^{2x+1}-9\cdot2^x+4\leqq0$ を解け．
  \item $x$ の方程式 $4^x-a\cdot2^{x+1}+a+2=0$ が異なる2つの実数解をもつような定数 $a$ の範囲を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 方程式 $2\log_4(x+1)+\log_2(x-2)=2$ を解け．
  \item 不等式 $\log_2x-2\log_x2<1$ を解け．
\end{enumerate}

次の連立方程式を解け．
\begin{enumerate}
  \item $2^x\cdot3^y=12,\quad 3^x\cdot2^y=18$
  \item $\log_xy+\log_yx=\dfrac52,\quad xy=27$
\end{enumerate}

\begin{enumerate}
  \item 実数 $a$ に対し，$f(x)=9^x+9^{-x}-2a(3^x+3^{-x})$ の最小値を $a$ で表せ．
  \item $x\geqq1,\ y\geqq1,\ xy=16$ のとき，$(\log_2x)(\log_2y)$ の最大値と最小値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 0でない実数 $x,y,z$ が $2^x=5^y=10^z$ を満たすとき，$\dfrac1x+\dfrac1y=\dfrac1z$ を示せ．
  \item 1でない正の数 $a,b,c$ が $\log_ab=\log_bc=\log_ca$ を満たすとき，$a=b=c$ を示せ．
\end{enumerate}

実数 $x$ に対して $t=2^x+2^{-x}$，$y=8^x+8^{-x}-3(4^x+4^{-x})-3(2^x+2^{-x})+12$ とおく．
\begin{enumerate}
  \item $y$ を $t$ の式で表せ．
  \item $y$ の最小値を求めよ．
  \item $a$ を実数とするとき，$y=a$ となる $x$ の個数を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 方程式 $9^{x+1}-3^{x+3}-3^x+3=0$ を解け．
  \item 不等式 $\left(\dfrac18\right)^{x+1}>\left(\dfrac14\right)^{2x-1}$ を解け．
  \item 不等式 $2^{2x+1}-9\cdot2^x+4\leqq0$ を解け．
\end{enumerate}

\begin{enumerate}
  \item 方程式 $\log_3(x-1)=\log_9(2x-3)+\log_9(x-2)$ を解け．
  \item 不等式 $2^{\log_3 9x}-5\cdot2^{\log_9x}+1\leqq0$ を解け．
  \item 不等式 $\dfrac12+\log_9(x^2+2x-3)\leqq\log_3(x+1)$ を解け．
\end{enumerate}

$\log_25=a$，$\log_53=b$ とする．
\begin{enumerate}
  \item $2^{ab}$ の値を求めよ．
  \item $3^{\frac{a+1}{ab}}$ の値を求めよ．
  \item $\log_{30}45$ を $a,b$ で表せ．
\end{enumerate}

$a,x,y$ は $12^x=18^y=a$ を満たす実数とする（$a>0,\ a\neq1$）．
\begin{enumerate}
  \item $\dfrac1x+\dfrac1y=3$ のとき，$a$ の値を求めよ．
  \item $\dfrac2x-\dfrac1y=3$ のとき，$a$ の値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 不等式 $\log_xy<1$ の表す領域を求めよ．
  \item 不等式 $\log_xy+\log_yx>2$ の表す領域を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\log_52$ の小数第1位の数字を求めよ．
  \item $\log_37$ の小数第1位の数字を求めよ．
\end{enumerate}

正の実数 $a,b$ が $1<a<b<a^2$ を満たすとき，$\log_ab$，$\log_ba$，$\log_a\dfrac ba$，$\log_b\dfrac ab$ について考える．
\begin{enumerate}
  \item $\log_ab$ のとりうる範囲を求め，$\log_ab$ が4つの中で最大，$\log_b\dfrac ab$ が最小であることを示せ．
  \item $\log_ba$ と $\log_a\dfrac ba$ の大小は $a,b$ によって変わる．$\log_ba>\log_a\dfrac ba$ となるための条件を，$b<a^k$ の形で表せ．
\end{enumerate}

関数 $y=9^x+9^{2-x}-14(3^x+3^{2-x})-13$ について，
\begin{enumerate}
  \item $y$ の最小値と，そのときの $x$ の値を求めよ．
  \item $x$ の方程式 $9^x+9^{2-x}-14(3^x+3^{2-x})-13=k$ が異なる4つの実数解をもつような $k$ の範囲を求めよ．
\end{enumerate}

$\log_{10}2=0.3010$，$\log_{10}3=0.4771$ とする．
\begin{enumerate}
  \item $3^{100}$ は何桁の数か．また，最高位の数字と一の位の数字を求めよ．
  \item $\left(\dfrac29\right)^{30}$ を小数で表すとき，初めて現れる0でない数字は小数第何位か．また，その数字を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 連立方程式 $x^y=y^x$，$\log_xy+\log_yx=\dfrac{10}3$ を解け．
  \item 実数 $x,y,z$ が $2^x+3^y+5^z=12$，$2^x+2\cdot3^y-5^z=6$ をみたしながら変わるとき，$2^x$ のとり得る値の範囲と，$4^x+3^{y+1}+3\cdot5^z$ のとり得る値の範囲を求めよ．
\end{enumerate}

$f(x)=\log_2(x+1)$（$x>-1$）とする．
\begin{enumerate}
  \item 不等式 $f(x)<x$ を解け．
  \item $f$ の逆関数 $f^{-1}(x)$ を求めよ．
  \item 増加関数 $f$ について $f(x)=f^{-1}(x)$ ならば $f(x)=x$ であることを示し，不等式 $\log_2(x+1)\geqq2^x-1$ を解け．
\end{enumerate}

方程式 $\left(\log_{10}\dfrac x2\right)\left(\log_{10}\dfrac5x\right)=\log_{10}\dfrac x{20}$ ……① について答えよ．
\begin{enumerate}
  \item ①は2つの相異なる正の実数解 $\alpha<\beta$ をもつことを示し，$\alpha\beta$ の値を求めよ．
  \item $\alpha,\ \beta,\ \frac1{10},\ 2,\ 10$ を小さい順に並べよ．
\end{enumerate}

$N=3^{40}+7^{20}$ とする．$\log_{10}3=0.4771$，$\log_{10}7=0.8451$，$\log_{10}1.2=0.0792$，$\log_{10}1.23=0.0899$ とする（いずれも小数第5位を四捨五入した値）．
\begin{enumerate}
  \item $N$ を100で割った余りを求めよ．
  \item $N$ の桁数と，上2桁の数を求めよ．
\end{enumerate}

$h(x)=2(8^x+8^{-x})-3(4^x+4^{-x})-3(2^x+2^{-x})+4$ とする．
\begin{enumerate}
  \item $t=2^x+2^{-x}$ とおくとき，$h(x)$ を $t$ で表し，因数分解せよ．
  \item 方程式 $h(x)=0$ を解け．
\end{enumerate}

次の関数 $f(x)$ について，$f\left(\dfrac{x+y}2\right)$ と $\dfrac12\{f(x)+f(y)\}$ の大小を比べよ（$x\neq y$）．
\begin{enumerate}
  \item $f(x)=\log_a(1+a^x)$（$a>0$，$a\neq1$）
  \item $f(x)=\log_a\dfrac x{1+x}$（$x>0$，$a>0$，$a\neq1$）
\end{enumerate}

\begin{enumerate}
  \item 方程式 $\log_3x+\log_9x=3(\log_3x)(\log_{27}x)$ を解け．
  \item $\log_{10}x+\log_{10}y=\log_{10}(y+x^2+3x+4)$ をみたす自然数の組 $(x,y)$ をすべて求めよ．
\end{enumerate}

次の不等式を解け．
\begin{enumerate}
  \item $\log_3|x-2|+\log_{\frac19}|x+4|<\dfrac12$
  \item $\log_{\frac12}\{\log_2(x+1)+\log_2(x-3)\}>-2$
\end{enumerate}

$a,b,c$ を正の実数とする（$a\neq1$）．実数 $x,y$ が $y=a^{bx+c}$ をみたすとき $\mathrm{LOG}_{a,b,c}\,y=x$ と表すことにする．
\begin{enumerate}
  \item $\mathrm{LOG}_{3,2,1}\,27$ の値を求めよ．
  \item $\mathrm{LOG}_{2,4,2}\,3=s$ とおく．$\log_881$ を $s$ で表せ．
  \item 等式 $\mathrm{LOG}_{3,2,1}(4t+13)-\mathrm{LOG}_{9,1,0}(t+1)-\mathrm{LOG}_{9,1,0}(t+3)=0$ をみたす実数 $t$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $x\leqq1$ かつ $3^x+a\cdot3^{-x}\leqq2$ をみたす実数 $x$ が存在するような $a$ の範囲を求めよ．
  \item $x\leqq1$ をみたすすべての $x$ に対し $3^x+a\cdot3^{-x}\geqq2a$ が成り立つような $a$ の範囲を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 方程式 $\log_4(x^2-4x+4)=3$ を解け．また，「$\log_4(x-2)^2=2\log_4(x-2)$」と変形して解くと，どの解が失われるか答えよ．
  \item 方程式 $\log_2x^2+\log_2(x+3)^2=4$ を解け．
  \item 不等式 $\log_{\frac12}x^2\geqq2\log_{\frac12}(x+2)$ を解け．
\end{enumerate}

\begin{enumerate}
  \item $2^{\frac12}$，$3^{\frac13}$，$4^{\frac14}$，$6^{\frac16}$，$7^{\frac17}$ を小さい順に並べよ（等しいものがあればそれも示せ）．
  \item 2以上の整数 $n$ に対して，$\log_n(n+1)>\log_{n+1}(n+2)$ を示せ．
  \item $\log_23$，$\log_34$，$\log_45$，$\dfrac54$ を大きい順に並べよ．
\end{enumerate}

$\log_{10}2=0.3010$，$\log_{10}3=0.4771$ とする．
\begin{enumerate}
  \item $2^{40}+3^{25}$ の桁数と最高位の数字を求めよ．
  \item $\left(\dfrac5{18}\right)^n$ を小数で表したとき，小数第7位まで0が並び，小数第8位に初めて0でない数字が現れるような整数 $n$ をすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item $a$ を実数とする．$x$ の方程式 $\log_2(x-1)=\log_4(ax-3)$ が異なる2つの実数解をもつような $a$ の範囲を求めよ．
  \item $a$ を実数とする．$x$ の方程式 $\log_3(a+9^x)=x+1$ の実数解の個数を $a$ の値によって分類し，解を求めよ．
\end{enumerate}

\begin{enumerate}
  \item すべての自然数 $n$ に対して $\left(1+\dfrac1n\right)^n<3$ を示せ．
  \item $3^{21}=10460353203$ である．$10^{10}<3^{21}<10^{10}\left(1+\dfrac1{21}\right)$ を確かめ，$\dfrac{10}{21}<\log_{10}3<\dfrac{21}{44}$ を示せ．
  \item $2^{10}<1000\left(1+\dfrac1{41}\right)$ を用いて，$\log_{10}2<\dfrac{247}{820}$ を示せ．
\end{enumerate}

$\log_{10}2=0.3010$，$\log_{10}3=0.4771$ とする．
\begin{enumerate}
  \item $5^{555}$ の桁数と最高位の数字を求めよ．
  \item 自然数 $n$ について，$5^n$ の最高位の数字が1であることは，$2^{n+1}$ の桁数が $2^n$ の桁数より大きいことと同値であることを示せ．
  \item $5^n$（$1\leqq n\leqq555$）のうち最高位の数字が1であるものの個数を求めよ．
\end{enumerate}

負でない実数 $x$ に対し，$0\leqq r<1$ で $x-r$ が整数となる $r$ を $\{x\}$ で表す．$0.3010<\log_{10}2<0.3011$，$0.4771<\log_{10}3<0.4772$ を用いてよい．
\begin{enumerate}
  \item $0.0100<\{10\log_{10}2\}<0.0110$ を示せ．
  \item $2^n$ の最高位の数字が9となる正の整数 $n$ を1つ求め，そのときの $2^n$ の桁数を求めよ．
  \item (2) で求めた $n$ について，$5^n$ の最高位の数字と桁数を求めよ．
\end{enumerate}

$N=(2\times3\times5\times7\times11\times13\times17)^{10}$ とする．常用対数表は用いないものとする．
\begin{enumerate}
  \item $N$ の10進法での桁数を求めよ．
  \item $N$ の最高位の数字を求めよ．
  \item $N$ の末尾に並ぶ0の個数と，0でない最も下の位の数字を求めよ．
\end{enumerate}

次の値を求めよ．
\begin{enumerate}
  \item $8^{\frac{2}{3}}\times 4^{-\frac{1}{2}}$
  \item $27^{\frac{1}{3}}\times 9^{-\frac{3}{2}}\times 81^{\frac{3}{4}}$
\end{enumerate}

次の式を簡単にせよ．
\begin{enumerate}
  \item $\sqrt[3]{54}-\sqrt[3]{16}+2\sqrt[3]{\dfrac{1}{4}}$
  \item $\sqrt[4]{12}\times\sqrt[4]{108}$
\end{enumerate}

$a>0$ で $a^{\frac{1}{2}}+a^{-\frac{1}{2}}=3$ のとき，次の値を求めよ．
\begin{enumerate}
  \item $a+a^{-1}$
  \item $a^{\frac{3}{2}}+a^{-\frac{3}{2}}$
\end{enumerate}

次の方程式を解け．
\begin{enumerate}
  \item $4^{x+1}=8^{x-1}$
  \item $9^{x}=\left(\dfrac{1}{27}\right)^{x-5}$
\end{enumerate}

次の不等式を解け．
\begin{enumerate}
  \item $\left(\dfrac{1}{3}\right)^{x}>9$
  \item $2^{3x-1}\leqq 4\cdot 2^{x}$
\end{enumerate}

次の値を求めよ．
\begin{enumerate}
  \item $\log_2 48-\log_2 3$
  \item $\log_3\sqrt{27}+2\log_{10}2+\log_{10}25$
\end{enumerate}

次の値を求めよ．
\begin{enumerate}
  \item $\log_4 8$
  \item $\log_4 9\cdot\log_{27}32$
\end{enumerate}

次の方程式を解け．
\begin{enumerate}
  \item $\log_2 x+\log_2(x-2)=3$
  \item $\log_3(x+1)+\log_3(x-1)=1$
\end{enumerate}

次の不等式を解け．
\begin{enumerate}
  \item $\log_{\frac{1}{2}}(x-1)>-2$
  \item $\log_3(x+3)\leqq \log_3 2x$
\end{enumerate}

$-1\leqq x\leqq 2$ のとき，次の関数のとりうる値の範囲を求めよ．
\begin{enumerate}
  \item $y=3^x$
  \item $y=\left(\dfrac{1}{2}\right)^{x-1}$
\end{enumerate}

$\log_{10}2=0.3010$，$\log_{10}3=0.4771$ とする．
\begin{enumerate}
  \item $2^{50}$ は何桁の整数か．
  \item $\left(\dfrac{1}{3}\right)^{10}$ を小数で表すと，小数第何位に初めて $0$ でない数字が現れるか．
\end{enumerate}

$\log_{10}2=a$，$\log_{10}3=b$ とするとき，次の値を $a$，$b$ で表せ．
\begin{enumerate}
  \item $\log_{10}12$
  \item $\log_{10}5$
\end{enumerate}

関数 $y=2^{x-1}+3$ について，次の問いに答えよ．
\begin{enumerate}
  \item このグラフは $y=2^x$ のグラフを $x$ 軸方向に $p$，$y$ 軸方向に $q$ だけ平行移動したものである．$p$，$q$ を求めよ．
  \item グラフの漸近線の方程式と，$y$ 軸との交点の $y$ 座標を求めよ．
\end{enumerate}

関数 $f(x)=4^x+4^{-x}-6(2^x+2^{-x})$ について，次の問いに答えよ．
\begin{enumerate}
  \item $t=2^x+2^{-x}$ とおくとき，$t$ のとりうる値の範囲を求めよ．また，$f(x)$ を $t$ の式で表せ．
  \item $f(x)$ の最小値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 方程式 $9^x-4\cdot 3^x+3=0$ を解け．
  \item 不等式 $9^x-4\cdot 3^x+3<0$ を解け．
  \item 不等式 $4^x-3\cdot 2^{x+1}+8\leqq 0$ を解け．
\end{enumerate}

\begin{enumerate}
  \item 方程式 $\log_2(x-1)=\log_4(x+5)$ を解け．
  \item 不等式 $\log_2(x-1)<\log_4(x+5)$ を解け．
\end{enumerate}

ある町の人口は毎年 $8\,\%$ ずつ増加するという．$\log_{10}2=0.3010$，$\log_{10}3=0.4771$ とする．
\begin{enumerate}
  \item $\log_{10}1.08$ の値を求めよ．
  \item 人口が初めて現在の $2$ 倍を超えるのは何年後か．
\end{enumerate}

$x$ の方程式 $4^x-2^{x+1}+a=0$ について，次の問いに答えよ．
\begin{enumerate}
  \item $a=-8$ のとき，方程式を解け．
  \item 方程式が異なる2つの実数解をもつような定数 $a$ の値の範囲を求めよ．
\end{enumerate}

$\log_2 3=a$，$\log_3 5=b$ とする．
\begin{enumerate}
  \item $\log_2 5$ を $a$，$b$ で表せ．
  \item $\log_{15}60$ を $a$，$b$ で表せ．
\end{enumerate}

$\log_{10}2=0.3010$，$\log_{10}3=0.4771$ とする．$\left(\dfrac{2}{3}\right)^{20}$ を小数で表したとき，
\begin{enumerate}
  \item 小数第何位に初めて $0$ でない数字が現れるか．
  \item その数字を求めよ．
\end{enumerate}

関数 $y=\log_2(4x-8)$ について，次の問いに答えよ．
\begin{enumerate}
  \item このグラフは，$y=\log_2 x$ のグラフを $x$ 軸方向に $p$，$y$ 軸方向に $q$ だけ平行移動したものである．$p$，$q$ を求めよ．
  \item このグラフと $x$ 軸との交点の $x$ 座標を求めよ．
  \item $y=\log_{\frac{1}{2}}(4x-8)$ のグラフは，$y=\log_2(4x-8)$ のグラフをある直線に関して対称移動したものである．その直線の方程式を求めよ．
\end{enumerate}

$x\leqq 1$ のとき，関数 $y=9^x-2\cdot3^{x+1}+10$ について，次の問いに答えよ．
\begin{enumerate}
  \item $t=3^x$ とおくとき，$t$ のとりうる値の範囲を求めよ．
  \item $y$ の最小値と，そのときの $x$ の値を求めよ．
\end{enumerate}

$2^{10}=1024$，$2^{13}=8192$ であることを用いて，次の問いに答えよ．
\begin{enumerate}
  \item $2^{10}>10^3$ の両辺の常用対数をとると，$\log_{10}2>p$ の形の不等式が得られる．有理数 $p$ を求めよ．
  \item $2^{13}<10^4$ の両辺の常用対数をとると，$\log_{10}2<q$ の形の不等式が得られる．有理数 $q$ を求めよ．
  \item (1)，(2) を用いて，$2^{100}$ の桁数を求めよ．
\end{enumerate}

以下の問いに答えよ．必要ならば，$0.3010<\log_{10}2<0.3011$ であることを用いてよい．
\begin{enumerate}
  \item $1\leqq n\leqq100$ をみたす整数 $n$ のうち，$5^n$ の最高位の数字が1であるものの個数を求めよ．
  \item $1\leqq n\leqq100$ をみたす整数 $n$ のうち，$5^n$ の最高位の数字が5以上であるものの個数を求めよ．
\end{enumerate}

$0.3010<\log_{10}2<0.3011$ であることは用いてよい．
\begin{enumerate}
  \item $\left(\dfrac54\right)^n$ の整数部分がちょうど3桁となる自然数 $n$ をすべて求めよ．
  \item 各正の整数 $k$ に対し，$\left(\dfrac54\right)^n$ の整数部分がちょうど $k$ 桁となる自然数 $n$ の個数は10または11であることを示せ．
\end{enumerate}

$N=2^{100}$ とする．必要なら $0.30102<\log_{10}2<0.30103$，$0.47712<\log_{10}3<0.47713$ を用いてよい．
\begin{enumerate}
  \item $N$ の桁数と最高位の数字を求めよ．
  \item $2^N$ の桁数を $n$ とする．$n$ の桁数と最高位の数字を求めよ．
\end{enumerate}
